public sealed interface Result<T, E> permits Result.Success, Result.Failure {
    record Success<T, E>(T value) implements Result<T, E> {}
    record Failure<T, E>(E error) implements Result<T, E> {}
}

static Result<Integer, String> parsePort(String s) {
    try { return new Result.Success<>(Integer.parseInt(s)); }
    catch (NumberFormatException e) { return new Result.Failure<>("not a number"); }
}

String label = switch (parsePort(raw)) {
    case Result.Success<Integer, String> ok  -> "port " + ok.value();
    case Result.Failure<Integer, String> bad -> "failed: " + bad.error();
};

